#include "securities_catalog_cache.hpp"
#include "securities_catalog_model.hpp"
#include <QDateTime>
#include <QRegularExpression>
#include <QCryptographicHash>
#include <QJsonDocument>
#include <QFile>
#include <QFileInfo>
#include <QDir>
#include <QSaveFile>
#include <QLockFile>
#include <stdexcept>
namespace securitiesCatalog {
namespace {
void need(bool ok,const char*message){if(!ok)throw std::runtime_error(message);}
QDateTime clock(QString t){auto at=QDateTime::fromString(t,Qt::ISODateWithMs);need(at.isValid()&&QRegularExpression("(Z|[+-][0-9]{2}:[0-9]{2})$").match(t).hasMatch(),"证券目录缓存时间必须带时区");return at;}
void validate(QString kind,QString query,const QJsonObject&r){need(r["items"].isArray()&&r["sourceTime"].isNull(),"公开缓存缺记录或伪造来源时刻");auto duration=clock(r["startedAt"].toString()).msecsTo(clock(r["fetchedAt"].toString()));need(duration>=0&&duration<=(kind=="directory"?120000:6000),"公开缓存抓取窗口无效");auto rows=r["items"].toArray();validateRows(rows);if(kind=="search"){need(r["schema"]=="native-securities-public-search/v1"&&r["query"]==query&&r["source"]=="sina-public-stock-lookup"&&r["sourceUrl"]==suggestionUrl(query).toString()&&r["coverageComplete"]==false&&rows.size()<=40,"公开检索不能当作完整目录");for(auto v:rows)need(v.toObject()["source"]=="sina-public-stock-lookup","检索来源混入其他记录");}else{need(r["schema"]=="native-securities-public-directory/v1"&&r["coverageComplete"]==true&&r["stockSourceUrl"]==(r["stockProvider"]=="sina-a-shares"?sinaPageUrl("SH",1):stockUrl(1)).toString()&&r["fundSourceUrl"]==fundUrl().toString()&&!r["scope"].toString().isEmpty(),"只有完整固定来源目录可保存");int stocks=0,funds=0;for(auto v:rows){auto src=v.toObject()["source"].toString();need(src==(r["stockProvider"]=="sina-a-shares"?"sina-a-shares":"eastmoney-a-shares")||src=="eastmoney-fund-file","目录来源混入其他记录");stocks+=src=="eastmoney-a-shares"||src=="sina-a-shares";funds+=src=="eastmoney-fund-file";}need(stocks>=1&&stocks<=20000&&funds>=1&&stocks==r["stockCount"].toInt(-1)&&funds==r["etfCount"].toInt(-1)&&r["fundInputRows"].toInt()>=funds&&r["fundInputRows"].toInt()<=50000,"公开目录完整数量不一致");if(r["stockProvider"]=="sina-a-shares")validateSinaCoverage(r);else need(!r.contains("stockProvider")||r["stockProvider"]=="eastmoney-a-shares","股票来源无效");}}
void write(QString file,const QJsonObject&value){auto bytes=QJsonDocument(value).toJson(QJsonDocument::Compact);need(bytes.size()<=32*1024*1024,"公开目录缓存超过32MiB");need(!QFileInfo(file).isSymLink()&&!QFileInfo(QFileInfo(file).absolutePath()).isSymLink(),"不覆盖链接目录/缓存");QSaveFile f(file);need(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size()&&f.commit(),"公开目录缓存保存失败，旧文件保留");}
}
Cache::Cache(QString p):directory(QDir(p).absolutePath()){need(!p.trimmed().isEmpty(),"公开目录需要专属缓存目录");}
QString Cache::path(QString kind,QString query)const{need(kind=="directory"||kind=="search","未知公开目录缓存分类");if(kind=="directory"){need(query.isEmpty(),"目录缓存不能带检索词");return directory+"/directory-v1.json";}suggestionUrl(query);return directory+"/lookup-"+QString::fromLatin1(QCryptographicHash::hash(query.toUtf8(),QCryptographicHash::Sha256).toHex())+".json";}
QJsonObject Cache::read(QString kind,QString query)const{auto file=path(kind,query);need(!QFileInfo(file).isSymLink()&&!QFileInfo(directory).isSymLink(),"不读取链接目录/缓存");if(!QFileInfo::exists(file))return {};QFile f(file);need(f.open(QIODevice::ReadOnly)&&f.size()>0&&f.size()<=32*1024*1024,"公开目录缓存不可读/超限");QJsonParseError e;auto d=QJsonDocument::fromJson(f.readAll(),&e);need(e.error==QJsonParseError::NoError&&d.isObject(),"公开目录缓存JSON损坏");auto result=d.object();need(result["schema"]=="native-securities-public-cache/v1"&&result["kind"]==kind&&result["query"]==query,"公开目录缓存身份不符");if(result.contains("result")){need(result["result"].isObject(),"公开目录缓存结果无效");validate(kind,query,result["result"].toObject());}auto attempt=result["lastAttempt"].toObject();clock(attempt["checkedAt"].toString());need(attempt["status"]=="success"||attempt["status"]=="failed","公开目录回执状态无效");need(attempt["error"].isNull()||attempt["error"].isString(),"公开目录错误回执无效");return result;}
void Cache::save(QString kind,QString query,const QJsonObject&result){validate(kind,query,result);auto file=path(kind,query);need(!QFileInfo(directory).isSymLink()&&QDir().mkpath(directory),"不能创建公开目录专属缓存");if(kind=="search"&&!QFileInfo::exists(file))need(QDir(directory).entryList({"lookup-*.json"},QDir::Files).size()<100,"公开检索缓存已达100项，旧缓存保留");QLockFile lock(file+".lock");need(lock.tryLock(500),"公开目录缓存写入忙");auto old=read(kind,query);auto before=old["result"].toObject();if(!before.isEmpty())need(clock(before["fetchedAt"].toString())<=clock(result["fetchedAt"].toString()),"较旧公开目录不能覆盖较新缓存");write(file,{{"schema","native-securities-public-cache/v1"},{"kind",kind},{"query",query},{"result",result},{"lastAttempt",QJsonObject{{"status","success"},{"checkedAt",result["fetchedAt"]},{"error",QJsonValue::Null}}}});}
void Cache::failure(QString kind,QString query,QString error,QString at){clock(at);need(!error.trimmed().isEmpty()&&error.size()<=1000,"公开目录失败回执无效");auto file=path(kind,query);need(!QFileInfo(directory).isSymLink()&&QDir().mkpath(directory),"不能创建公开目录专属缓存");QLockFile lock(file+".lock");need(lock.tryLock(500),"公开目录缓存写入忙");auto saved=read(kind,query);if(saved.isEmpty())saved={{"schema","native-securities-public-cache/v1"},{"kind",kind},{"query",query}};auto prior=saved["lastAttempt"].toObject();if(!prior.isEmpty()&&clock(prior["checkedAt"].toString())>clock(at))return;saved["lastAttempt"]=QJsonObject{{"status","failed"},{"checkedAt",at},{"error",error}};write(file,saved);}
}
